import sys, json, re

# AN APP READS ITS ROUND OFF THE WALL (curator, GH #949). An app of a member
# that runs a round of its own -- a nightly pass, a digest, a follow-up -- had
# one way into what was said: the memory hive's recall. The curator's ledger,
# the one record of every turn its model saw, had no reader outside the hive:
# `./history` answers the model's own `history_*` tool calls and nobody else.
# This cell is that reader, on the lane `in_read`, answered on `read`:
#
#   turns     the wall rows of the round, oldest first after the cursor
#             `since` (a `seq`), optionally of one `session_id`: `seq`,
#             `session_id`, `turn_id`, `kind`, `origin`, `final`, `at` and the
#             `text` of the stored block. At most `limit` rows (default 20, at
#             most 100) and `read_budget` characters of text a page; `next` is
#             the cursor to ask with for the rest, or '' at the end.
#   sessions  the sessions of the round with their first and last row (`seq`,
#             `at`) and their number of turns, newest first, out of the newest
#             `scan_budget` rows after `since`; `truncated` says that there was
#             more than the answer holds.
#
# THE ROUND IS THE KEY AND NOTHING ELSE OPENS THE WALL (GH #925, GH #932). The
# round is `context.audience_set` of the message being served -- for an app the
# context of the message it reacts to, since a cell writes no context -- and a
# row reaches it iff the row's own audience covers it: the store's `covers`
# operator selects (`round_where`), so a row of another round is never read
# and no page, cursor or count can tell it was there; the gate below is the
# second line. A row without an audience (from before the rule, NULL) reaches
# no round. FAIL-CLOSED: a read without a round -- none, unparsable, or the
# declared empty round, which names nobody who could be reading -- is answered
# `missing_audience` before a single ledger read. A store that refuses a read
# is answered `store_error`, never as an empty page: "the read failed" must not
# look like "there is nothing" (the argus door's rule, GH #928).
#
# THE QUESTION. `hop.read_tag` (1 to 64 characters) is echoed on every answer,
# a refusal too, so the asker matches the answer to its question; the body
# carries `{what, session_id?, since?, limit?}`. `since` and `limit` are whole
# numbers or strings of ASCII digits; `session_id` is not looked at for
# `sessions`. Checked in the order round, `read_tag`, `what`, `session_id`,
# `since`, `limit`; the first key that fails is named in `hop.detail` with
# `invalid_input`, and nothing is read. Every answer carries `hop.error_code`
# -- empty on an answer -- so an answer can never be mistaken for a question
# (the request edge `install_app` draws takes only a `read` without one).
#
# Read only: no write, no mark, no model. Two ledger round trips for a page of
# turns (the rows, then their blocks), one for the sessions.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


# THE AUDIENCE GATE (GH #925): the same text as in every other cell of this hive
# that reads rows (`./history`, `./push`, ...), held to one table by a lock.
def audience_of(value):
    """An audience in its canonical form -- a JSON array of strings, sorted,
    no duplicates, no whitespace -- or None when there is none. The round
    arrives as TEXT (a JSON array in a string) and a column comes back as
    text; a list is taken as it is. Absent, empty text, a scalar or
    unparsable text is NOT DECLARED: the empty list is a declared round, None
    is no round at all (affinity `as_set`, GH #306)."""
    if isinstance(value, str):
        if not value.strip():
            return None
        try:
            value = json.loads(value)
        except ValueError:
            return None
    if not isinstance(value, list):
        return None
    return json.dumps(sorted({str(x) for x in value if str(x)}), separators=(",", ":"))


def allowed(round_value, origin):
    """The gate: a row whose audience is `origin` may reach the round
    `round_value` iff both are declared and the origin names `*` or holds the
    round as a subset. A row from before the rule has no origin and never
    leaves (OR-BD-5); a round nobody declared passes nothing."""
    r, o = audience_of(round_value), audience_of(origin)
    if r is None or o is None:
        return False
    o = set(json.loads(o))
    return "*" in o or set(json.loads(r)) <= o


def passes(row, round_value, session):
    """One reader's verdict on one row. With a declared round it is the gate;
    without one, only a row of the running session that declares no round
    either (or names `*`) passes -- the window and the handover keep a
    round-less conversation going and show nothing from elsewhere (OR-BD-4).
    A row of a declared round never reaches a call nobody declared a round
    for, though it stands in the same session (review M-7: the words of {e,b}
    reached a round-less call of that session, and a round-less recall took
    the addendum of an {e,a} gap). A row that names no session never passes
    a round-less read."""
    if audience_of(round_value) is None:
        if not session or str(row.get("session_id") or "") != session:
            return False
        own = audience_of(row.get("audience_set"))
        return own is not None and (own == "[]" or "*" in json.loads(own))
    return allowed(round_value, row.get("audience_set"))


ROUNDLESS = ["[]", "[\"*\"]"]


def round_where(round_value, session):
    """The store half of the audience gate (GH #932): the `where` terms a
    ledger read adds so that only rows this round may see come back -- page
    bounds, `scanned`, window and renewal sizes and turn counts then hang on
    visible rows alone, and a hidden row costs nothing a reader can count.
    With a declared, non-empty round it is `covers` (the affinity rule in the
    store). Without one -- or with a declared EMPTY round, which `covers`
    refuses -- only rows of the running session that declare no round either
    (`[]`, PP-BD-12) or name `*` come back; a row from before the rule (NULL)
    never does. None: nothing may be read at all (no round and no session).
    The Python gate below stays as the second line."""
    r = audience_of(round_value)
    if r is not None and r != "[]":
        return {"audience_set": {"covers": json.loads(r)}}
    if not session:
        return None
    return {"session_id": session, "audience_set": {"in": list(ROUNDLESS)}}


def audience_meet(values):
    """The audience of a row made of other rows (a summary, a handover
    block): the INTERSECTION of its sources, so it can never be wider than
    any of them (OR-BD-3). A source naming `*` is neutral; one source without
    an audience, or no source at all, makes the result None."""
    out, universal = None, False
    for v in values:
        c = audience_of(v)
        if c is None:
            return None
        s = set(json.loads(c))
        if "*" in s:
            universal = True
            continue
        out = s if out is None else out & s
    if out is None:
        return '["*"]' if universal else None
    return json.dumps(sorted(out), separators=(",", ":"))




def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    return int(float(v))


# The knobs. The literal beside each name is the shipped default, the same
# number `params` and `contract.settings` carry.
READ_BUDGET = max(1, _int("read_budget", 40000))
SCAN_BUDGET = max(1, _int("scan_budget", 5000))

ME = "curator-reader"
WHATS = ("turns", "sessions")
LIMIT_DEFAULT = 20
LIMIT_MAX = 100
TAG_MAX = 64
SESSION_MAX = 256
# A `seq` is microseconds since the epoch (`./intake`); a cursor is a whole
# number inside the store's signed 64-bit integer.
SEQ_MAX = 2 ** 63 - 1
DIGITS = re.compile(r"[0-9]{1,19}")
WALL_COLS = ["seq", "session_id", "turn_id", "kind", "hash", "final", "at", "audience_set"]
SESSION_COLS = ["seq", "session_id", "turn_id", "at", "audience_set"]

# The round this message is served in, out of its context in every step: this
# hive's edges set and delete only `cur_*`, so it rides every ledger round trip
# like `cur_origin` -- and it is never read out of a row or out of the body.
ROUND = ctx.get("audience_set")
CANON = audience_of(ROUND)
# The store's half of the gate (GH #932). Only a declared, non-empty round
# reads; the round-less branch of `round_where` (the running session's
# undeclared rows) serves the model of a running conversation, and an app
# reading the wall has none.
RW = round_where(ROUND, "") if CANON not in (None, "[]") else None
NO_ROUND = ("this read declares no round (context.audience_set) -- nothing of "
            "the wall is read for it")


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason):
    sys.stderr.write("curator/reader: %s\n" % reason)
    emit([])


def echo(v):
    """A value of the question, bounded, for the answer to carry back."""
    return v[:TAG_MAX] if isinstance(v, str) else ""


def answer(tag, what, rows, nxt="", code="", detail="", truncated=False):
    """The one `read` of a question. `code` empty = an answer; a refusal
    carries its code and no rows, and is never an empty page of an answer."""
    return {"header": {"route": "read", "read_tag": tag, "read_what": what,
                       "error_code": code, "detail": detail},
            "messages": [], "rows": rows, "next": nxt, "truncated": truncated}


def refuse(tag, what, code, detail):
    emit([answer(tag, what, [], "", code, detail)])


def _blank(v):
    # An edge that always writes a key writes "" where it means "not set".
    return v is None or v == ""


def _whole(v):
    """A whole number from a JSON integer or a string of ASCII digits; a bool,
    a float and every other spelling are no count (the argus door's rule)."""
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return v
    if isinstance(v, str) and DIGITS.fullmatch(v):
        return int(v)
    return None


def parse(body):
    """The question of the body, or the key it is refused on: `(request,
    None)` or `(None, key)`, in the order `what`, `session_id`, `since`,
    `limit`."""
    if not isinstance(body, dict):
        return None, "what"
    what = body.get("what")
    if not isinstance(what, str) or what not in WHATS:
        return None, "what"
    sid = ""
    if what == "turns" and not _blank(body.get("session_id")):
        sid = body.get("session_id")
        if not isinstance(sid, str) or len(sid) > SESSION_MAX:
            return None, "session_id"
    since = 0
    if not _blank(body.get("since")):
        since = _whole(body.get("since"))
        if since is None or not 0 <= since <= SEQ_MAX:
            return None, "since"
    limit = LIMIT_DEFAULT
    if not _blank(body.get("limit")):
        limit = _whole(body.get("limit"))
        if limit is None or not 1 <= limit <= LIMIT_MAX:
            return None, "limit"
    return {"what": what, "session_id": sid, "since": since, "limit": limit}, None


def sel(table, columns, where, order, limit):
    return {"operation": "select", "table": table, "columns": columns, "where": where,
            "order_by": [{"col": c, "dir": o} for c, o in order], "limit": limit}


def lstore(ops, phase, tag, carry):
    """One message to `./ledger`. Every key the hive's edge reads is always
    present (a failed CEL modifier skips the edge): `cur_call` carries the tag
    and `cur_reason` the question across the store's answer."""
    return {"header": {"route": "lstore", "phase": phase, "reply_cell": ME,
                       "cur_call": tag, "cur_reason": json.dumps(carry, sort_keys=True)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def wall_where(req):
    """The `where` of a wall read of this round: the store's gate first, then
    the cursor and the session. A key of the gate wins (`round_where` names
    only `audience_set` for a declared round)."""
    where = {}
    if req["since"]:
        where["seq"] = {"gt": req["since"]}
    if req["session_id"]:
        where["session_id"] = req["session_id"]
    return dict(where, **RW)


def legs(body):
    """The answer of a store message by tool_call id: payload and error code,
    for a bundle (`results[]`) and for a single op alike."""
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def shown(rs):
    """The rows among `rs` this round may see, in their order -- the second
    line behind the store's `covers` (GH #925)."""
    return [r for r in rs if isinstance(r, dict) and allowed(ROUND, r.get("audience_set"))]


def element_of(body):
    try:
        el = json.loads(str(body or "null"))
    except Exception:
        return None
    return el if isinstance(el, dict) else None


def turn_rows(page, bodies):
    """The rows of one page with their text, whole while the page stays within
    `read_budget` characters; the first row always goes, its text cut at the
    budget (`cut`) when it alone is larger, so a reader always moves on."""
    out, used = [], 0
    for r in page:
        el = element_of(bodies.get(str(r.get("hash") or ""))) or {}
        text = str(el.get("text") or "")
        if out and used + len(text) > READ_BUDGET:
            break
        entry = {"seq": int(r.get("seq") or 0), "session_id": str(r.get("session_id") or ""),
                 "turn_id": str(r.get("turn_id") or ""), "kind": str(r.get("kind") or ""),
                 "origin": str(el.get("origin") or ""), "final": int(r.get("final") or 0),
                 "at": str(r.get("at") or ""), "text": text}
        if len(text) > READ_BUDGET:
            entry["text"], entry["cut"] = text[:READ_BUDGET], True
        used += len(entry["text"])
        out.append(entry)
    return out


def session_rows(seen, limit):
    """The sessions among `seen` (newest first), each with its first and last
    row and its number of turns, newest first; the first `limit` and whether
    there were more."""
    by = {}
    for r in seen:
        sid = str(r.get("session_id") or "")
        seq, at = int(r.get("seq") or 0), str(r.get("at") or "")
        s = by.get(sid)
        if s is None:
            s = by[sid] = {"session_id": sid, "first_seq": seq, "last_seq": seq,
                           "first_at": at, "last_at": at, "turns": set()}
        if seq < s["first_seq"]:
            s["first_seq"], s["first_at"] = seq, at
        if seq > s["last_seq"]:
            s["last_seq"], s["last_at"] = seq, at
        s["turns"].add(str(r.get("turn_id") or ""))
    out = sorted(by.values(), key=lambda s: (-s["last_seq"], s["session_id"]))
    for s in out:
        s["turns"] = len(s["turns"])
    return out[:limit], len(out) > limit


# =================================================================== LANES
lane = str(hop.get("route") or "")

if lane == "in_read":
    tag = echo(hop.get("read_tag"))
    what = echo((d if isinstance(d, dict) else {}).get("what"))
    # GH #949: fail-closed on the round, before the question is looked at --
    # no argument could make the wall readable to a read without one.
    if RW is None:
        refuse(tag, what, "missing_audience", NO_ROUND)
    raw_tag = hop.get("read_tag")
    if not isinstance(raw_tag, str) or not 1 <= len(raw_tag) <= TAG_MAX:
        refuse(tag, what, "invalid_input", "read_tag")
    req, bad = parse(d)
    if bad:
        refuse(tag, what, "invalid_input", bad)
    if req["what"] == "turns":
        emit([lstore([("t-wall", sel("wall", WALL_COLS, wall_where(req), [("seq", "asc")],
                                     req["limit"] + 1))], "turns", tag, req)])
    where = wall_where(dict(req, session_id=""))
    emit([lstore([("s-wall", sel("wall", SESSION_COLS, where, [("seq", "desc")],
                                 SCAN_BUDGET + 1))], "sessions", tag, req)])

if lane:
    park("unknown lane %r -- dropped" % lane)
if "operation" not in hop:
    park("a message with neither a lane nor a store answer -- dropped")

phase = str(ctx.get("cur_phase") or "")
tag = str(ctx.get("cur_call") or "")
try:
    req = json.loads(str(ctx.get("cur_reason") or "") or "{}")
except Exception:
    req = None
if not isinstance(req, dict) or req.get("what") not in WHATS:
    park("store answer in phase %r without its question -- dropped" % phase)
what = req["what"]
if RW is None:
    # The round rides the context through every ledger round trip; a store
    # answer that lost it on the way shows nothing of what was read.
    sys.stderr.write("curator/reader: a store answer in phase %s without its round\n" % phase)
    refuse(tag, what, "missing_audience", NO_ROUND)
lg = legs(d)
failed = sorted({leg["error_code"] for leg in lg.values() if leg["error_code"]})
if failed or not lg:
    # The ledger refusing a read is this hive's failure, said here and answered
    # there -- never as a page without rows.
    sys.stderr.write("curator/reader: ledger refused the read in phase %s\n" % phase)
    refuse(tag, what, "store_error", ",".join(failed) or "ledger")

if phase == "turns":
    seen = shown(rows(lg, "t-wall"))
    limit = int(req.get("limit") or LIMIT_DEFAULT)
    page = seen[:limit]
    if not page:
        emit([answer(tag, what, [])])
    carry = dict(req, more=len(seen) > limit,
                 page=[{k: r.get(k) for k in WALL_COLS if k != "audience_set"} for r in page])
    hashes = sorted({str(r.get("hash") or "") for r in page})
    emit([lstore([("t-blocks", sel("blocks", ["hash", "body"], {"hash": {"in": hashes}},
                                   [("hash", "asc")], len(hashes)))], "turns-2", tag, carry)])

if phase == "turns-2":
    page = [r for r in req.get("page") or [] if isinstance(r, dict)]
    bodies = {str(r.get("hash") or ""): str(r.get("body") or "")
              for r in rows(lg, "t-blocks") if isinstance(r, dict)}
    out = turn_rows(page, bodies)
    more = bool(req.get("more")) or len(out) < len(page)
    emit([answer(tag, what, out, str(out[-1]["seq"]) if more and out else "")])

if phase == "sessions":
    seen = shown(rows(lg, "s-wall"))
    limit = int(req.get("limit") or LIMIT_DEFAULT)
    listed, more = session_rows(seen[:SCAN_BUDGET], limit)
    emit([answer(tag, what, listed, "", truncated=more or len(seen) > SCAN_BUDGET)])

park("store answer in unknown phase %r -- dropped" % phase)
